use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn analyze_directory (dir : & str , generate : bool) -> Result < () > { println ! ("📊 Analyzing AST patterns in: {}" , dir) ; let mut function_count = 0 ; let mut struct_count = 0 ; let mut enum_count = 0 ; let mut impl_count = 0 ; let mut complex_functions = Vec :: new () ; for entry in walkdir :: WalkDir :: new (dir) { let entry = entry ? ; if entry . file_type () . is_file () && entry . path () . extension () . map_or (false , | ext | ext == "rs") { let content = std :: fs :: read_to_string (entry . path ()) ? ; if let Ok (syntax_tree) = syn :: parse_str :: < syn :: File > (& content) { for item in & syntax_tree . items { match item { syn :: Item :: Fn (func) => { function_count += 1 ; if func . sig . ident . to_string () . len () > 20 { complex_functions . push (func . sig . ident . to_string ()) ; } } syn :: Item :: Struct (_) => struct_count += 1 , syn :: Item :: Enum (_) => enum_count += 1 , syn :: Item :: Impl (_) => impl_count += 1 , _ => { } } } } } } println ! ("📈 Analysis Results:") ; println ! ("  Functions: {}" , function_count) ; println ! ("  Structs: {}" , struct_count) ; println ! ("  Enums: {}" , enum_count) ; println ! ("  Impls: {}" , impl_count) ; println ! ("  Complex functions: {}" , complex_functions . len ()) ; if generate { println ! ("\n🔧 Generating targeted probes based on analysis...") ; let mut probes = Vec :: new () ; if ! complex_functions . is_empty () { probes . push (AstProbe { name : "monitor_complex_functions" . to_string () , node_type : split_decls_rs :: ast_reflector :: AstNodeType :: Function , filter : split_decls_rs :: ast_reflector :: ProbeFilter { name_pattern : None , visibility : None , attributes : vec ! [] , contains_text : None , complexity_threshold : Some (8.0) , layer : None , } , action : split_decls_rs :: ast_reflector :: ProbeAction :: Log { message : "Complex function detected - consider refactoring" . to_string () , } , enabled : true , priority : 1 , }) ; } if struct_count > 10 { probes . push (AstProbe { name : "document_public_structs" . to_string () , node_type : split_decls_rs :: ast_reflector :: AstNodeType :: Struct , filter : split_decls_rs :: ast_reflector :: ProbeFilter { name_pattern : None , visibility : Some ("pub" . to_string ()) , attributes : vec ! [] , contains_text : None , complexity_threshold : None , layer : None , } , action : split_decls_rs :: ast_reflector :: ProbeAction :: AddAttribute { attr : "#[doc = \"Auto-generated documentation\"]" . to_string () , } , enabled : true , priority : 2 , }) ; } let json = serde_json :: to_string_pretty (& probes) ? ; std :: fs :: write ("generated_probes.json" , json) ? ; println ! ("💾 Generated probes saved to: generated_probes.json") ; } Ok (()) }